import argparse
import sys

def createparser():
    """Create an ArgumentParser for the pysemver CLI."""
    parser = argparse.ArgumentParser(prog='pysemver', description='Semantic Versioning CLI')
    subparsers = parser.add_subparsers(dest='command', required=True)

    # bump command
    bump_parser = subparsers.add_parser('bump', help='Bump a version component')
    bump_parser.add_argument('version', help='original version string')
    bump_parser.add_argument('component', choices=['major','minor','patch','prerelease','build'], help='component to bump')

    # replace command
    replace_parser = subparsers.add_parser('replace', help='Replace components of a version')
    replace_parser.add_argument('version', help='original version string')
    replace_parser.add_argument('--major', type=int)
    replace_parser.add_argument('--minor', type=int)
    replace_parser.add_argument('--patch', type=int)
    replace_parser.add_argument('--prerelease')
    replace_parser.add_argument('--build')

    # compare command
    compare_parser = subparsers.add_parser('compare', help='Compare two versions')
    compare_parser.add_argument('v1')
    compare_parser.add_argument('v2')

    return parser

def process(args):
    """Process parsed arguments and return result string."""
    if args.command == 'bump':
        if args.component == 'major':
            return bump_major(args.version)
        if args.component == 'minor':
            return bump_minor(args.version)
        if args.component == 'patch':
            return bump_patch(args.version)
        if args.component == 'prerelease':
            return bump_prerelease(args.version)
        if args.component == 'build':
            return bump_build(args.version)
    if args.command == 'replace':
        kwargs = {k: v for k, v in vars(args).items() if k in ('major','minor','patch','prerelease','build') and v is not None}
        return replace(args.version, **kwargs)
    if args.command == 'compare':
        return str(compare(args.v1, args.v2))
    return ''

def main(argv=None):
    if argv is None:
        argv = sys.argv[1:]
    parser = createparser()
    args = parser.parse_args(argv)
    result = process(args)
    if result is not None:
        print(result)
    return result

if __name__ == '__main__':
    main()
